package dev.amaan.employees;
import java.math.BigDecimal;
import java.util.UUID;
/** Validated employee data. IDs are generated by the application, never edited by users. */
public record Employee(String id, String name, String email, String department, BigDecimal salary) {
    public Employee {
        if (id == null) throw new IllegalArgumentException("Employee ID is required.");
        UUID.fromString(id);
        name = required(name, "Name", 120);
        email = required(email, "Email", 254);
        department = required(department, "Department", 120);
        if (!email.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))
            throw new IllegalArgumentException("Enter a valid email address.");
        if (salary == null || salary.signum() < 0 || salary.scale() > 2 || salary.compareTo(new BigDecimal("9999999999.99")) > 0)
            throw new IllegalArgumentException("Salary must be non-negative, at most 9999999999.99, with up to two decimals.");
    }
    private static String required(String value, String label, int limit) {
        if (value == null || value.isBlank() || value.strip().length() > limit)
            throw new IllegalArgumentException(label + " is required (maximum " + limit + " characters).");
        return value.strip();
    }
}
